// Eva - Calculator REPL

use std::collections::VecDeque;
use std::fmt;
use std::io::{self, BufRead, Write};

// ============ ERRORS ============

#[derive(Debug, Clone)]
pub enum CalcError {
    /// Syntax error with message
    Syntax(String),
    /// Parser error with message  
    Parser(String),
    /// Math error with message
    Math(String),
    /// Domain error with message
    Domain(String),
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CalcError::Syntax(msg) => write!(f, "Syntax Error: {}", msg),
            CalcError::Parser(msg) => write!(f, "Parser Error: {}", msg),
            CalcError::Math(msg) => write!(f, "Math Error: {}", msg),
            CalcError::Domain(msg) => write!(f, "Domain Error: {}", msg),
        }
    }
}

// ============ TOKENS ============

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Number(f64),
    Plus,
    Minus,
    Multiply,
    Divide,
    Power,
    LParen,
    RParen,
    Comma,
    Function(String),
    Constant(String),
}

// ============ FUNCTIONS ============

fn is_function(name: &str) -> bool {
    matches!(name, 
        "sin" | "cos" | "tan" | "csc" | "sec" | "cot" |
        "sinh" | "cosh" | "tanh" |
        "asin" | "acos" | "atan" | "acsc" | "asec" | "acot" |
        "ln" | "log2" | "log10" | "sqrt" | "ceil" | "floor" | "abs" |
        "log" | "nroot"
    )
}

fn is_constant(name: &str) -> bool {
    matches!(name, "pi" | "e")
}

fn function_arg_count(name: &str) -> usize {
    match name {
        "log" | "nroot" => 2,
        _ => 1,
    }
}

// ============ LEXER ============

pub fn tokenize(input: &str) -> Result<Vec<Token>, CalcError> {
    let chars: Vec<char> = input.chars().collect();
    let mut tokens: Vec<Token> = Vec::new();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        match c {
            ' ' | '\t' => { i += 1; }
            '+' => { tokens.push(Token::Plus); i += 1; }
            '-' => { tokens.push(Token::Minus); i += 1; }
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    tokens.push(Token::Power);
                    i += 2;
                } else {
                    tokens.push(Token::Multiply);
                    i += 1;
                }
            }
            '/' => { tokens.push(Token::Divide); i += 1; }
            '^' => { tokens.push(Token::Power); i += 1; }
            '(' => { tokens.push(Token::LParen); i += 1; }
            ')' => { tokens.push(Token::RParen); i += 1; }
            ',' => { tokens.push(Token::Comma); i += 1; }
            '0'..='9' | '.' => {
                let start = i;
                while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    i += 1;
                }
                let num_str: String = chars[start..i].iter().collect();
                match num_str.parse::<f64>() {
                    Ok(n) => tokens.push(Token::Number(n)),
                    Err(_) => return Err(CalcError::Syntax(format!("Invalid number '{}'", num_str))),
                }
            }
            'a'..='z' | 'A'..='Z' => {
                let start = i;
                while i < chars.len() && (chars[i].is_ascii_alphabetic() || chars[i].is_ascii_digit()) {
                    i += 1;
                }
                let name: String = chars[start..i].iter().collect();

                if is_function(&name) {
                    tokens.push(Token::Function(name));
                } else if is_constant(&name) {
                    tokens.push(Token::Constant(name));
                } else {
                    return Err(CalcError::Syntax(format!("Unexpected character '{}'", name)));
                }
            }
            '_' => {
                // underscore = previous answer, treat as a special constant
                tokens.push(Token::Constant("_".to_string()));
                i += 1;
            }
            _ => {
                return Err(CalcError::Syntax(format!("Unexpected character '{}'", c)));
            }
        }
    }

    Ok(tokens)
}

// ============ IMPLICIT MULTIPLICATION ============

fn insert_implicit_mult(tokens: Vec<Token>) -> Vec<Token> {
    let mut result = Vec::new();

    for i in 0..tokens.len() {
        if i > 0 {
            let prev = &tokens[i - 1];
            let curr = &tokens[i];

            let insert = match (prev, curr) {
                // number followed by function or constant
                (Token::Number(_), Token::Function(_)) => true,
                (Token::Number(_), Token::Constant(_)) => true,
                // number followed by (
                (Token::Number(_), Token::LParen) => true,
                // constant followed by number
                (Token::Constant(_), Token::Number(_)) => true,
                // constant followed by (
                // (would make constant a function, handled in lexer)
                // ) followed by (
                (Token::RParen, Token::LParen) => true,
                // ) followed by function - nah, that would break things
                _ => false,
            };

            if insert {
                result.push(Token::Multiply);
            }
        }
        result.push(tokens[i].clone());
    }

    result
}

// ============ VALIDATE FUNCTIONS ============

fn validate_functions(tokens: &[Token]) -> Result<(), CalcError> {
    for i in 0..tokens.len() {
        if let Token::Function(name) = &tokens[i] {
            // Function must be followed by LParen
            if i + 1 >= tokens.len() || tokens[i + 1] != Token::LParen {
                return Err(CalcError::Syntax(format!("Function '{}' expected parentheses", name)));
            }
        }
    }
    Ok(())
}

// ============ AUTO-BALANCE PARENTHESES ============

fn balance_parens(tokens: Vec<Token>) -> Vec<Token> {
    let mut depth = 0i32;
    for t in &tokens {
        match t {
            Token::LParen => depth += 1,
            Token::RParen => depth -= 1,
            _ => {}
        }
    }

    let mut result = tokens;
    for _ in 0..depth {
        result.push(Token::RParen);
    }
    result
}

// ============ SHUNTING YARD ============

#[derive(Debug, Clone, PartialEq)]
enum OpType {
    Plus,
    Minus,
    Multiply,
    Divide,
    Power,
    UnaryMinus,
    UnaryPlus,
    Function(String),
}

impl OpType {
    fn precedence(&self) -> i32 {
        match self {
            OpType::Plus | OpType::Minus => 2,
            OpType::Multiply | OpType::Divide => 3,
            OpType::Power => 4,
            OpType::UnaryMinus | OpType::UnaryPlus => 5,
            OpType::Function(_) => 6,
        }
    }

    fn is_right_assoc(&self) -> bool {
        matches!(self, OpType::Power | OpType::UnaryMinus | OpType::UnaryPlus)
    }
}

#[derive(Debug, Clone)]
enum ShuntItem {
    Number(f64),
    Op(OpType),
    Function(String),
    Comma,
    LParen,
}

pub fn shunting_yard(tokens: &[Token]) -> Result<VecDeque<ShuntItem>, CalcError> {
    let mut output: VecDeque<ShuntItem> = VecDeque::new();
    let mut op_stack: Vec<ShuntItem> = Vec::new();
    let mut arg_count_stack: Vec<usize> = Vec::new();

    let mut prev_token: Option<&Token> = None;

    for token in tokens {
        match token {
            Token::Number(n) => {
                output.push_back(ShuntItem::Number(*n));
            }
            Token::Constant(name) => {
                let val = match name.as_str() {
                    "pi" => std::f64::consts::PI,
                    "e" => std::f64::consts::E,
                    "_" => {
                        // Will be replaced with previous answer
                        // We push a special marker
                        output.push_back(ShuntItem::Number(f64::NAN)); // placeholder
                        prev_token = Some(token);
                        continue;
                    }
                    _ => unreachable!(),
                };
                output.push_back(ShuntItem::Number(val));
            }
            Token::Function(name) => {
                op_stack.push(ShuntItem::Function(name.clone()));
                arg_count_stack.push(1);
            }
            Token::Comma => {
                // Pop until LParen
                loop {
                    match op_stack.last() {
                        None => return Err(CalcError::Parser("Mismatched parentheses".to_string())),
                        Some(ShuntItem::LParen) => break,
                        Some(_) => {
                            let op = op_stack.pop().unwrap();
                            output.push_back(op);
                        }
                    }
                }
                if let Some(count) = arg_count_stack.last_mut() {
                    *count += 1;
                }
            }
            Token::Plus | Token::Minus => {
                // Determine if unary or binary
                let is_unary = match prev_token {
                    None => true,
                    Some(Token::Plus) | Some(Token::Minus) |
                    Some(Token::Multiply) | Some(Token::Divide) |
                    Some(Token::Power) | Some(Token::LParen) |
                    Some(Token::Comma) => true,
                    _ => false,
                };

                let op = if is_unary {
                    if *token == Token::Plus {
                        OpType::UnaryPlus
                    } else {
                        OpType::UnaryMinus
                    }
                } else {
                    if *token == Token::Plus {
                        OpType::Plus
                    } else {
                        OpType::Minus
                    }
                };

                let prec = op.precedence();
                let right_assoc = op.is_right_assoc();

                loop {
                    match op_stack.last() {
                        Some(ShuntItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if (top_prec > prec) || (top_prec == prec && !right_assoc) {
                                let item = op_stack.pop().unwrap();
                                output.push_back(item);
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }

                op_stack.push(ShuntItem::Op(op));
            }
            Token::Multiply => {
                let op = OpType::Multiply;
                let prec = op.precedence();
                loop {
                    match op_stack.last() {
                        Some(ShuntItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !op.is_right_assoc()) {
                                let item = op_stack.pop().unwrap();
                                output.push_back(item);
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                op_stack.push(ShuntItem::Op(op));
            }
            Token::Divide => {
                let op = OpType::Divide;
                let prec = op.precedence();
                loop {
                    match op_stack.last() {
                        Some(ShuntItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !op.is_right_assoc()) {
                                let item = op_stack.pop().unwrap();
                                output.push_back(item);
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                op_stack.push(ShuntItem::Op(op));
            }
            Token::Power => {
                let op = OpType::Power;
                let prec = op.precedence();
                let right_assoc = op.is_right_assoc();
                loop {
                    match op_stack.last() {
                        Some(ShuntItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !right_assoc) {
                                let item = op_stack.pop().unwrap();
                                output.push_back(item);
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                op_stack.push(ShuntItem::Op(op));
            }
            Token::LParen => {
                op_stack.push(ShuntItem::LParen);
            }
            Token::RParen => {
                loop {
                    match op_stack.last() {
                        None => return Err(CalcError::Parser("Mismatched parentheses".to_string())),
                        Some(ShuntItem::LParen) => {
                            op_stack.pop();
                            break;
                        }
                        Some(_) => {
                            let item = op_stack.pop().unwrap();
                            output.push_back(item);
                        }
                    }
                }
                // If there's a function on top, pop it
                if let Some(ShuntItem::Function(_)) = op_stack.last() {
                    let func = op_stack.pop().unwrap();
                    let argc = arg_count_stack.pop().unwrap_or(1);
                    output.push_back(ShuntItem::Number(argc as f64)); // arg count
                    output.push_back(func);
                }
            }
        }

        prev_token = Some(token);
    }

    // Pop remaining operators
    while let Some(item) = op_stack.pop() {
        match item {
            ShuntItem::LParen | ShuntItem::Function(_) => {
                return Err(CalcError::Parser("Mismatched parentheses".to_string()));
            }
            _ => output.push_back(item),
        }
    }

    Ok(output)
}

// ============ EVALUATOR ============

pub fn evaluate(rpn: &VecDeque<ShuntItem>, prev_ans: f64, angle_unit: &AngleUnit) -> Result<f64, CalcError> {
    let mut stack: Vec<f64> = Vec::new();

    for item in rpn {
        match item {
            ShuntItem::Number(n) => {
                if n.is_nan() {
                    // This is the placeholder for previous answer
                    stack.push(prev_ans);
                } else {
                    stack.push(*n);
                }
            }
            ShuntItem::Op(op) => {
                match op {
                    OpType::UnaryMinus => {
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(-a);
                    }
                    OpType::UnaryPlus => {
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a);
                    }
                    OpType::Plus => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a + b);
                    }
                    OpType::Minus => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a - b);
                    }
                    OpType::Multiply => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a * b);
                    }
                    OpType::Divide => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        if b == 0.0 {
                            return Err(CalcError::Math("Divide by zero error!".to_string()));
                        }
                        stack.push(a / b);
                    }
                    OpType::Power => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a.powf(b));
                    }
                    OpType::Function(_) => unreachable!(),
                }
            }
            ShuntItem::Function(name) => {
                let argc = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))? as usize;
                let expected = function_arg_count(name);

                if argc < expected {
                    return Err(CalcError::Parser(format!("To few arguments for function, need {}", expected)));
                }
                if argc > expected {
                    return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                }

                let result = if expected == 1 {
                    let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                    eval_function1(name, a, angle_unit)?
                } else {
                    let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                    let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                    eval_function2(name, a, b)?
                };

                stack.push(result);
            }
            ShuntItem::Comma => {}
            ShuntItem::LParen => {}
        }
    }

    if stack.len() == 1 {
        Ok(stack[0])
    } else if stack.is_empty() {
        Err(CalcError::Parser("Too many operators, too few operands".to_string()))
    } else {
        Err(CalcError::Parser("Too many operators, too few operands".to_string()))
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum AngleUnit {
    Degree,
    Radian,
    Gradian,
}

fn to_radians(val: f64, unit: &AngleUnit) -> f64 {
    match unit {
        AngleUnit::Radian => val,
        AngleUnit::Degree => val * std::f64::consts::PI / 180.0,
        AngleUnit::Gradian => val * std::f64::consts::PI / 200.0,
    }
}

fn from_radians(val: f64, unit: &AngleUnit) -> f64 {
    match unit {
        AngleUnit::Radian => val,
        AngleUnit::Degree => val * 180.0 / std::f64::consts::PI,
        AngleUnit::Gradian => val * 200.0 / std::f64::consts::PI,
    }
}

fn eval_function1(name: &str, a: f64, angle: &AngleUnit) -> Result<f64, CalcError> {
    match name {
        "sin" => Ok(to_radians(a, angle).sin()),
        "cos" => Ok(to_radians(a, angle).cos()),
        "tan" => Ok(to_radians(a, angle).tan()),
        "csc" => {
            let s = to_radians(a, angle).sin();
            if s == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(1.0 / s)
        }
        "sec" => {
            let c = to_radians(a, angle).cos();
            if c == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(1.0 / c)
        }
        "cot" => {
            let s = to_radians(a, angle).sin();
            if s == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(to_radians(a, angle).cos() / s)
        }
        "sinh" => Ok(a.sinh()),
        "cosh" => Ok(a.cosh()),
        "tanh" => Ok(a.tanh()),
        "asin" => {
            if a < -1.0 || a > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians(a.asin(), angle))
        }
        "acos" => {
            if a < -1.0 || a > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians(a.acos(), angle))
        }
        "atan" => Ok(from_radians(a.atan(), angle)),
        "acsc" => {
            if a.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians((1.0/a).asin(), angle))
        }
        "asec" => {
            if a.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians((1.0/a).acos(), angle))
        }
        "acot" => {
            Ok(from_radians((1.0/a).atan(), angle))
        }
        "ln" => {
            if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.ln())
        }
        "log2" => {
            if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.log2())
        }
        "log10" => {
            if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.log10())
        }
        "sqrt" => {
            if a < 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.sqrt())
        }
        "ceil" => Ok(a.ceil()),
        "floor" => Ok(a.floor()),
        "abs" => Ok(a.abs()),
        _ => Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
    }
}

fn eval_function2(name: &str, a: f64, b: f64) -> Result<f64, CalcError> {
    match name {
        "log" => {
            // log(x, base) = log_base(x)
            if a <= 0.0 || b <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.ln() / b.ln())
        }
        "nroot" => {
            // nroot(x, n) = x^(1/n)
            Ok(a.powf(1.0 / b))
        }
        _ => Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
    }
}

// ============ OUTPUT FORMATTING ============

/// Format a number with the given base and number of decimal places
pub fn format_number(n: f64, base: u32, fix: usize) -> String {
    if base == 10 {
        format_base10(n, fix)
    } else {
        format_base_n(n, base, fix)
    }
}

fn format_base10(n: f64, fix: usize) -> String {
    let negative = n < 0.0;
    let abs_n = n.abs();

    // Format with fix decimal places
    let formatted = format!("{:.prec$}", abs_n, prec = fix);

    // Split into integer and decimal parts
    let (int_part, dec_part) = if let Some(pos) = formatted.find('.') {
        (&formatted[..pos], &formatted[pos..])
    } else {
        (formatted.as_str(), "")
    };

    // Add comma separators to integer part
    let int_with_commas = add_commas(int_part);

    if negative {
        format!("-{}{}", int_with_commas, dec_part)
    } else {
        format!("{}{}", int_with_commas, dec_part)
    }
}

fn add_commas(s: &str) -> String {
    let len = s.len();
    if len <= 3 {
        return s.to_string();
    }

    let mut result = String::new();
    let first_group = len % 3;

    if first_group > 0 {
        result.push_str(&s[..first_group]);
    }

    let mut i = first_group;
    while i < len {
        if !result.is_empty() {
            result.push(',');
        }
        result.push_str(&s[i..i+3]);
        i += 3;
    }

    result
}

fn format_base_n(n: f64, base: u32, fix: usize) -> String {
    let negative = n < 0.0;
    let abs_n = n.abs();

    let int_part = abs_n.floor() as u64;
    let frac_part = abs_n - abs_n.floor();

    // Convert integer part to base N
    let int_str = if int_part == 0 {
        "0".to_string()
    } else {
        to_base_n(int_part, base)
    };

    // Pad integer to at least 10 digits
    let padded = if int_str.len() < 10 {
        format!("{:>10}", int_str)
    } else {
        int_str
    };

    // Group with commas every 3 from right
    let int_grouped = group_digits(&padded);

    // Convert fractional part
    let frac_str = if fix > 0 {
        let mut frac = frac_part;
        let mut digits = String::new();
        for _ in 0..fix {
            frac *= base as f64;
            let digit = frac.floor() as u32;
            digits.push(digit_to_char(digit));
            frac -= frac.floor();
        }
        digits
    } else {
        String::new()
    };

    let result = if negative {
        format!("-{}.{}", int_grouped, frac_str)
    } else {
        format!("{}.{}", int_grouped, frac_str)
    };

    result
}

fn to_base_n(mut n: u64, base: u32) -> String {
    if n == 0 {
        return "0".to_string();
    }

    let mut digits = Vec::new();
    while n > 0 {
        digits.push(digit_to_char((n % base as u64) as u32));
        n /= base as u64;
    }
    digits.reverse();
    digits.into_iter().collect()
}

fn digit_to_char(d: u32) -> char {
    if d < 10 {
        (b'0' + d as u8) as char
    } else {
        (b'A' + (d - 10) as u8) as char
    }
}

fn group_digits(s: &str) -> String {
    // The string may have leading spaces (padding)
    // We need to group every 3 digits from the right, preserving spaces in groups
    let len = s.len();
    if len == 0 {
        return String::new();
    }

    // Group from right
    let mut result = String::new();
    let first_group_size = len % 3;
    let first_group_size = if first_group_size == 0 { 3 } else { first_group_size };

    result.push_str(&s[..first_group_size]);

    let mut i = first_group_size;
    while i < len {
        result.push(',');
        result.push_str(&s[i..i+3]);
        i += 3;
    }

    result
}

// ============ MAIN PROCESSING ============

pub fn process_expression(input: &str, prev_ans: f64, angle_unit: &AngleUnit, base: u32, fix: usize) -> Result<f64, CalcError> {
    let tokens = tokenize(input)?;
    let tokens = insert_implicit_mult(tokens);
    validate_functions(&tokens)?;
    let tokens = balance_parens(tokens);
    let rpn = shunting_yard(&tokens)?;
    let result = evaluate(&rpn, prev_ans, angle_unit)?;
    Ok(result)
}

