}

fn print_version() {
    println!("eva 0.3.1");
}

fn parse_args() -> Result<Config, String> {
    let args: Vec<String> = std::env::args().collect();

    let mut fix = 10usize;
    let mut base = 10u32;
    let mut angle_unit = AngleUnit::Degree;
    let mut input = None;
    let mut i = 1;
    let mut end_of_options = false;

    while i < args.len() {
        let arg = &args[i];

        if end_of_options {
            if input.is_some() {
                return Err(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: eva [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg));
            }
            input = Some(arg.clone());
            i += 1;
            continue;
        }

        if arg == "--" {
            end_of_options = true;
            i += 1;
            continue;
        }

        if arg == "-h" || arg == "--help" {
            print_help();
            std::process::exit(0);
        }

        if arg == "-V" || arg == "--version" {
            print_version();
            std::process::exit(0);
        }

        if arg == "-f" || arg == "--fix" {
            i += 1;
            if i >= args.len() {
                return Err(format!("'--fix' requires a value but none was supplied"));
            }
            let val = &args[i];
            fix = val.parse::<usize>().map_err(|_| {
                format!("invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val)
            })?;
            if fix < 1 || fix > 64 {
                return Err(format!("invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", val, val));
            }
            i += 1;
            continue;
        }

        if arg.starts_with("--fix=") {
            let val = &arg[6..];
            fix = val.parse::<usize>().map_err(|_| {
                format!("invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val)
            })?;
            if fix < 1 || fix > 64 {
                return Err(format!("invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", val, val));
            }
            i += 1;
            continue;
        }

        if arg.starts_with("-f") && arg.len() > 2 {
            let val = &arg[2..];
            fix = val.parse::<usize>().map_err(|_| {
                format!("invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val)
            })?;
            if fix < 1 || fix > 64 {
                return Err(format!("invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", val, val));
            }
            i += 1;
            continue;
        }

        if arg == "-b" || arg == "--base" {
            i += 1;
            if i >= args.len() {
                return Err(format!("'--base' requires a value but none was supplied"));
            }
            let val = &args[i];
            base = val.parse::<u32>().map_err(|_| {
                format!("invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val)
            })?;
            if base < 1 || base > 36 {
                return Err(format!("invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", val, val));
            }
            i += 1;
            continue;
        }

        if arg.starts_with("--base=") {
            let val = &arg[7..];
            base = val.parse::<u32>().map_err(|_| {
                format!("invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val)
            })?;
            if base < 1 || base > 36 {
                return Err(format!("invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", val, val));
            }
            i += 1;
            continue;
        }

        if arg.starts_with("-b") && arg.len() > 2 {
            let val = &arg[2..];
            base = val.parse::<u32>().map_err(|_| {
                format!("invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val)
            })?;
            if base < 1 || base > 36 {
                return Err(format!("invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", val, val));
            }
            i += 1;
            continue;
        }

        if arg == "-a" || arg == "--angle_unit" {
            i += 1;
            if i >= args.len() {
                return Err(format!("'--angle_unit' requires a value but none was supplied"));
            }
            let val = &args[i];
            angle_unit = match val.as_str() {
                "degree" => AngleUnit::Degree,
                "radian" => AngleUnit::Radian,
                "gradian" => AngleUnit::Gradian,
                _ => return Err(format!("invalid value '{}' for '--angle_unit <angle_unit>': invalid variant", val)),
            };
            i += 1;
            continue;
        }

        if arg.starts_with("--angle_unit=") {
            let val = &arg[13..];
            angle_unit = match val {
                "degree" => AngleUnit::Degree,
                "radian" => AngleUnit::Radian,
                "gradian" => AngleUnit::Gradian,
                _ => return Err(format!("invalid value '{}' for '--angle_unit <angle_unit>': invalid variant", val)),
            };
            i += 1;
            continue;
        }

        if arg.starts_with('-') && !end_of_options {
            // Unknown option or negative number
            return Err(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: eva [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg));
        }

        // Positional argument
        if input.is_some() {
            return Err(format!("unexpected argument '{}' found", arg));
        }
        input = Some(arg.clone());
        i += 1;
    }

    Ok(Config { fix, base, angle_unit, input })
}

// ============ HISTORY ============

fn get_history_path() -> Option<std::path::PathBuf> {
    let home = std::env::var("HOME").ok()?;
    let mut path = std::path::PathBuf::from(home);
    path.push(".local/share/eva");
    Some(path)
}

fn load_history(path: &std::path::Path) -> Vec<String> {
    let hist_file = path.join("history.txt");
    if let Ok(content) = std::fs::read_to_string(&hist_file) {
        content.lines()
            .filter(|l| !l.starts_with('#'))
            .map(|l| l.to_string())
            .collect()
    } else {
        Vec::new()
    }
}

fn save_history(path: &std::path::Path, history: &[String]) {
    let _ = std::fs::create_dir_all(path);
    let hist_file = path.join("history.txt");
    let content = format!("#V2\n{}", history.join("\n"));
    let _ = std::fs::write(&hist_file, content);
}

// ============ REPL ============

fn run_repl(config: &Config) {
    let hist_dir = get_history_path();
    let mut history: Vec<String> = Vec::new();
    let mut history_exists = false;

    if let Some(ref path) = hist_dir {
        let hist_file = path.join("history.txt");
        if hist_file.exists() {
            history = load_history(path);
            history_exists = true;
        }
    }

    if !history_exists {
        println!("No previous history.");
    }

    let mut prev_ans = 0.0f64;
    let stdin = io::stdin();

    // Check if stdin is a terminal
    let is_tty = unsafe { libc::isatty(0) } == 1;

    if is_tty {
        // Interactive mode - show prompt
        loop {
            print!("> ");
            let _ = io::stdout().flush();

            let mut line = String::new();
            match stdin.lock().read_line(&mut line) {
                Ok(0) => break, // EOF
                Ok(_) => {
                    let trimmed = line.trim().to_string();
                    if trimmed.is_empty() {
                        continue;
                    }

                    history.push(trimmed.clone());

                    match process_expression(&trimmed, prev_ans, &config.angle_unit, config.base, config.fix) {
                        Ok(result) => {
                            prev_ans = result;
                            println!("{}", format_number(result, config.base, config.fix));
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                        }
                    }
                }
                Err(_) => break,
            }
        }
    } else {
        // Non-interactive mode - no prompt
        for line in stdin.lock().lines() {
            match line {
                Ok(l) => {
                    let trimmed = l.trim().to_string();
                    if trimmed.is_empty() {
                        continue;
                    }

                    history.push(trimmed.clone());

                    match process_expression(&trimmed, prev_ans, &config.angle_unit, config.base, config.fix) {
                        Ok(result) => {
                            prev_ans = result;
                            println!("{}", format_number(result, config.base, config.fix));
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                        }
                    }
                }
                Err(_) => break,
            }
        }
    }

    // Save history
    if let Some(ref path) = hist_dir {
        save_history(path, &history);
    }
}

// ============ MAIN ============

extern "C" {
    fn isatty(fd: i32) -> i32;
}

mod libc {
    pub unsafe fn isatty(fd: i32) -> i32 {
        unsafe { super::isatty(fd) }
    }
}

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(2);
        }
    };

    if let Some(ref input) = config.input {
        // Command mode
        match process_expression(input, 0.0, &config.angle_unit, config.base, config.fix) {
            Ok(result) => {
                println!("{}", format_number(result, config.base, config.fix));
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    } else {
        // REPL mode
        run_repl(&config);
    }
}
