// ============ ANGLE UNIT ============

#[derive(Clone, Debug, PartialEq)]
pub enum AngleUnit {
    Degree,
    Radian,
    Gradian,
}

fn to_radians(val: f64, unit: &AngleUnit) -> f64 {
    match unit {
        AngleUnit::Radian => val,
        AngleUnit::Degree => val * std::f64::consts::PI / 180.0,
        AngleUnit::Gradian => val * std::f64::consts::PI / 200.0,
    }
}

fn from_radians(val: f64, unit: &AngleUnit) -> f64 {
    match unit {
        AngleUnit::Radian => val,
        AngleUnit::Degree => val * 180.0 / std::f64::consts::PI,
        AngleUnit::Gradian => val * 200.0 / std::f64::consts::PI,
    }
}

// ============ TOKENS ============

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Number(f64),
    Plus,
    Minus,
    Multiply,
    Divide,
    Power,
    LParen,
    RParen,
    Comma,
    Function(String),
    Constant(String),
    Prev, // underscore
}

// ============ FUNCTIONS ============

fn is_function(name: &str) -> bool {
    matches!(name,
        "sin" | "cos" | "tan" | "csc" | "sec" | "cot" |
        "sinh" | "cosh" | "tanh" |
        "asin" | "acos" | "atan" | "acsc" | "asec" | "acot" |
        "ln" | "log2" | "log10" | "sqrt" | "ceil" | "floor" | "abs" |
        "log" | "nroot"
    )
}

fn is_constant(name: &str) -> bool {
    matches!(name, "pi" | "e")
}

fn function_arg_count(name: &str) -> usize {
    match name {
        "log" | "nroot" => 2,
        _ => 1,
    }
}

// ============ LEXER ============

pub fn tokenize(input: &str) -> Result<Vec<Token>, CalcError> {
    let chars: Vec<char> = input.chars().collect();
    let mut tokens: Vec<Token> = Vec::new();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        match c {
            ' ' | '\t' => { i += 1; }
            '+' => { tokens.push(Token::Plus); i += 1; }
            '-' => { tokens.push(Token::Minus); i += 1; }
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    tokens.push(Token::Power);
                    i += 2;
                } else {
                    tokens.push(Token::Multiply);
                    i += 1;
                }
            }
            '/' => { tokens.push(Token::Divide); i += 1; }
            '^' => { tokens.push(Token::Power); i += 1; }
            '(' => { tokens.push(Token::LParen); i += 1; }
            ')' => { tokens.push(Token::RParen); i += 1; }
            ',' => { tokens.push(Token::Comma); i += 1; }
            '_' => { tokens.push(Token::Prev); i += 1; }
            '0'..='9' | '.' => {
                let start = i;
                while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    i += 1;
                }
                let num_str: String = chars[start..i].iter().collect();
                match num_str.parse::<f64>() {
                    Ok(n) => tokens.push(Token::Number(n)),
                    Err(_) => return Err(CalcError::Syntax(format!("Invalid number '{}'", num_str))),
                }
            }
            'a'..='z' | 'A'..='Z' => {
                let start = i;
                while i < chars.len() && chars[i].is_ascii_alphabetic() {
                    i += 1;
                }
                let name: String = chars[start..i].iter().collect();

                // Try to match longest function name first, then shorter ones
                // The lexer greedily matches alphabetic chars, then checks if it's
                // a known function or constant
                if is_function(&name) {
                    tokens.push(Token::Function(name));
                } else if is_constant(&name) {
                    tokens.push(Token::Constant(name));
                } else {
                    // Try to find a valid prefix (e.g., "log2" contains "log" but also digits)
                    return Err(CalcError::Syntax(format!("Unexpected character '{}'", name)));
                }
            }
            _ => {
                return Err(CalcError::Syntax(format!("Unexpected character '{}'", c)));
            }
        }
    }

    Ok(tokens)
}

// ============ IMPLICIT MULTIPLICATION ============

fn insert_implicit_mult(tokens: Vec<Token>) -> Vec<Token> {
    let mut result = Vec::new();

    for i in 0..tokens.len() {
        if i > 0 {
            let prev = &tokens[i - 1];
            let curr = &tokens[i];

            let insert = match (prev, curr) {
                // number followed by function or constant or prev-ans
                (Token::Number(_), Token::Function(_)) => true,
                (Token::Number(_), Token::Constant(_)) => true,
                (Token::Number(_), Token::Prev) => true,
                // number followed by (
                (Token::Number(_), Token::LParen) => true,
                // constant followed by number
                (Token::Constant(_), Token::Number(_)) => true,
                // prev-ans followed by number
                (Token::Prev, Token::Number(_)) => true,
                // ) followed by (
                (Token::RParen, Token::LParen) => true,
                // ) followed by function - no implicit mult
                _ => false,
            };

            if insert {
                result.push(Token::Multiply);
            }
        }
        result.push(tokens[i].clone());
    }

    result
}

// ============ VALIDATE FUNCTIONS ============

fn validate_functions(tokens: &[Token]) -> Result<(), CalcError> {
    for i in 0..tokens.len() {
        if let Token::Function(name) = &tokens[i] {
            if i + 1 >= tokens.len() || tokens[i + 1] != Token::LParen {
                return Err(CalcError::Syntax(format!("Function '{}' expected parentheses", name)));
            }
        }
    }
    Ok(())
}

// ============ AUTO-BALANCE PARENTHESES ============

fn balance_parens(tokens: Vec<Token>) -> Vec<Token> {
    let mut depth = 0i32;
    for t in &tokens {
        match t {
            Token::LParen => depth += 1,
            Token::RParen => { if depth > 0 { depth -= 1; } }
            _ => {}
        }
    }

    let mut result = tokens;
    for _ in 0..depth {
        result.push(Token::RParen);
    }
    result
}

// ============ SHUNTING YARD ============

#[derive(Debug, Clone, PartialEq)]
enum OpType {
    Plus,
    Minus,
    Multiply,
    Divide,
    Power,
    UnaryMinus,
    UnaryPlus,
}

impl OpType {
    fn precedence(&self) -> i32 {
        match self {
            OpType::Plus | OpType::Minus => 2,
            OpType::Multiply | OpType::Divide => 3,
            OpType::Power => 4,
            OpType::UnaryMinus | OpType::UnaryPlus => 5,
        }
    }

    fn is_right_assoc(&self) -> bool {
        matches!(self, OpType::Power | OpType::UnaryMinus | OpType::UnaryPlus)
    }
}

#[derive(Debug, Clone)]
enum RpnToken {
    Number(f64),
    Prev,
    Op(OpType),
    Function(String, usize), // (name, arg_count)
}

pub fn shunting_yard(tokens: &[Token]) -> Result<Vec<RpnToken>, CalcError> {
    let mut output: Vec<RpnToken> = Vec::new();
    let mut op_stack: Vec<(Option<OpType>, Option<String>)> = Vec::new(); // (op, func_name) or LParen
    // For LParen: (None, None)
    // For ops: (Some(op), None)
    // For funcs: (None, Some(name))

    // Actually let's use a proper enum for the stack
    enum StackItem {
        Op(OpType),
        Function(String),
        LParen(usize), // arg count so far
    }

    let mut stack: Vec<StackItem> = Vec::new();
    let mut prev_token: Option<&Token> = None;

    for token in tokens {
        match token {
            Token::Number(n) => {
                output.push(RpnToken::Number(*n));
            }
            Token::Prev => {
                output.push(RpnToken::Prev);
            }
            Token::Constant(name) => {
                let val = match name.as_str() {
                    "pi" => std::f64::consts::PI,
                    "e" => std::f64::consts::E,
                    _ => unreachable!(),
                };
                output.push(RpnToken::Number(val));
            }
            Token::Function(name) => {
                stack.push(StackItem::Function(name.clone()));
            }
            Token::Comma => {
                // Pop until LParen
                loop {
                    match stack.last() {
                        None => return Err(CalcError::Parser("Mismatched parentheses".to_string())),
                        Some(StackItem::LParen(_)) => break,
                        Some(_) => {
                            if let Some(StackItem::Op(op)) = stack.pop() {
                                output.push(RpnToken::Op(op));
                            }
                        }
                    }
                }
                // Increment arg count for the LParen
                if let Some(StackItem::LParen(ref mut count)) = stack.last_mut() {
                    *count += 1;
                }
            }
            Token::Plus | Token::Minus => {
                let is_unary = match prev_token {
                    None => true,
                    Some(Token::Plus) | Some(Token::Minus) |
                    Some(Token::Multiply) | Some(Token::Divide) |
                    Some(Token::Power) | Some(Token::LParen) |
                    Some(Token::Comma) => true,
                    _ => false,
                };

                let op = if is_unary {
                    if *token == Token::Plus { OpType::UnaryPlus } else { OpType::UnaryMinus }
                } else {
                    if *token == Token::Plus { OpType::Plus } else { OpType::Minus }
                };

                let prec = op.precedence();
                let right_assoc = op.is_right_assoc();

                loop {
                    match stack.last() {
                        Some(StackItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !right_assoc) {
                                if let Some(StackItem::Op(top)) = stack.pop() {
                                    output.push(RpnToken::Op(top));
                                }
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                stack.push(StackItem::Op(op));
            }
            Token::Multiply => {
                let op = OpType::Multiply;
                let prec = op.precedence();
                loop {
                    match stack.last() {
                        Some(StackItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !op.is_right_assoc()) {
                                if let Some(StackItem::Op(top)) = stack.pop() {
                                    output.push(RpnToken::Op(top));
                                }
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                stack.push(StackItem::Op(op));
            }
            Token::Divide => {
                let op = OpType::Divide;
                let prec = op.precedence();
                loop {
                    match stack.last() {
                        Some(StackItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !op.is_right_assoc()) {
                                if let Some(StackItem::Op(top)) = stack.pop() {
                                    output.push(RpnToken::Op(top));
                                }
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                stack.push(StackItem::Op(op));
            }
            Token::Power => {
                let op = OpType::Power;
                let prec = op.precedence();
                let right_assoc = op.is_right_assoc();
                loop {
                    match stack.last() {
                        Some(StackItem::Op(top_op)) => {
                            let top_prec = top_op.precedence();
                            if top_prec > prec || (top_prec == prec && !right_assoc) {
                                if let Some(StackItem::Op(top)) = stack.pop() {
                                    output.push(RpnToken::Op(top));
                                }
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                stack.push(StackItem::Op(op));
            }
            Token::LParen => {
                stack.push(StackItem::LParen(1)); // start with 1 arg
            }
            Token::RParen => {
                loop {
                    match stack.last() {
                        None => return Err(CalcError::Parser("Mismatched parentheses".to_string())),
                        Some(StackItem::LParen(_)) => {
                            break;
                        }
                        Some(_) => {
                            if let Some(StackItem::Op(op)) = stack.pop() {
                                output.push(RpnToken::Op(op));
                            }
                        }
                    }
                }

                let argc = if let Some(StackItem::LParen(count)) = stack.pop() {
                    count
                } else {
                    1
                };

                // Check if there's a function on top
                if let Some(StackItem::Function(_)) = stack.last() {
                    if let Some(StackItem::Function(name)) = stack.pop() {
                        output.push(RpnToken::Function(name, argc));
                    }
                }
            }
        }

        prev_token = Some(token);
    }

    // Pop remaining operators
    while let Some(item) = stack.pop() {
        match item {
            StackItem::LParen(_) => {
                return Err(CalcError::Parser("Mismatched parentheses".to_string()));
            }
            StackItem::Function(_) => {
                return Err(CalcError::Parser("Mismatched parentheses".to_string()));
            }
            StackItem::Op(op) => {
                output.push(RpnToken::Op(op));
            }
        }
    }

    Ok(output)
}

// ============ EVALUATOR ============

pub fn evaluate(rpn: &[RpnToken], prev_ans: f64, angle_unit: &AngleUnit) -> Result<f64, CalcError> {
    let mut stack: Vec<f64> = Vec::new();

    for item in rpn {
        match item {
            RpnToken::Number(n) => {
                stack.push(*n);
            }
            RpnToken::Prev => {
                stack.push(prev_ans);
            }
            RpnToken::Op(op) => {
                match op {
                    OpType::UnaryMinus => {
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(-a);
                    }
                    OpType::UnaryPlus => {
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a);
                    }
                    OpType::Plus => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a + b);
                    }
                    OpType::Minus => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a - b);
                    }
                    OpType::Multiply => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a * b);
                    }
                    OpType::Divide => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        if b == 0.0 {
                            return Err(CalcError::Math("Divide by zero error!".to_string()));
                        }
                        stack.push(a / b);
                    }
                    OpType::Power => {
                        let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                        stack.push(a.powf(b));
                    }
                }
            }
            RpnToken::Function(name, argc) => {
                let expected = function_arg_count(name);

                if *argc < expected {
                    return Err(CalcError::Parser(format!("To few arguments for function, need {}", expected)));
                }
                if *argc > expected {
                    return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                }

                let result = if expected == 1 {
                    let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                    eval_function1(name, a, angle_unit)?
                } else {
                    let b = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                    let a = stack.pop().ok_or_else(|| CalcError::Parser("Too many operators, too few operands".to_string()))?;
                    eval_function2(name, a, b)?
                };

                stack.push(result);
            }
        }
    }

    if stack.len() == 1 {
        Ok(stack[0])
    } else if stack.is_empty() {
        Err(CalcError::Parser("Too many operators, too few operands".to_string()))
    } else {
        Err(CalcError::Parser("Too many operators, too few operands".to_string()))
    }
}

fn eval_function1(name: &str, a: f64, angle: &AngleUnit) -> Result<f64, CalcError> {
    match name {
        "sin" => Ok(to_radians(a, angle).sin()),
        "cos" => Ok(to_radians(a, angle).cos()),
        "tan" => Ok(to_radians(a, angle).tan()),
        "csc" => {
            let s = to_radians(a, angle).sin();
            if s == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(1.0 / s)
        }
        "sec" => {
            let c = to_radians(a, angle).cos();
            if c == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(1.0 / c)
        }
        "cot" => {
            let s = to_radians(a, angle).sin();
            if s == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(to_radians(a, angle).cos() / s)
        }
        "sinh" => Ok(a.sinh()),
        "cosh" => Ok(a.cosh()),
        "tanh" => Ok(a.tanh()),
        "asin" => {
            if a < -1.0 || a > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians(a.asin(), angle))
        }
        "acos" => {
            if a < -1.0 || a > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians(a.acos(), angle))
        }
        "atan" => Ok(from_radians(a.atan(), angle)),
        "acsc" => {
            if a.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians((1.0/a).asin(), angle))
        }
        "asec" => {
            if a.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(from_radians((1.0/a).acos(), angle))
        }
        "acot" => {
            Ok(from_radians((1.0/a).atan(), angle))
        }
        "ln" => {
            if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.ln())
        }
        "log2" => {
            if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.log2())
        }
        "log10" => {
            if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.log10())
        }
        "sqrt" => {
            if a < 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.sqrt())
        }
        "ceil" => Ok(a.ceil()),
        "floor" => Ok(a.floor()),
        "abs" => Ok(a.abs()),
        _ => Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
    }
}

fn eval_function2(name: &str, a: f64, b: f64) -> Result<f64, CalcError> {
    match name {
        "log" => {
            if a <= 0.0 || b <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
            Ok(a.ln() / b.ln())
        }
        "nroot" => {
            Ok(a.powf(1.0 / b))
        }
        _ => Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
    }
}

// ============ OUTPUT FORMATTING ============

pub fn format_number(n: f64, base: u32, fix: usize) -> String {
    if base == 10 {
        format_base10(n, fix)
    } else {
        format_base_n(n, base, fix)
    }
}

fn format_base10(n: f64, fix: usize) -> String {
    let negative = n < 0.0;
    let abs_n = n.abs();

    let formatted = format!("{:.prec$}", abs_n, prec = fix);

    // Split into integer and decimal parts
    let dot_pos = formatted.find('.').unwrap_or(formatted.len());
    let int_part = &formatted[..dot_pos];
    let dec_part = &formatted[dot_pos..]; // includes the '.'

    let int_with_commas = add_commas_base10(int_part);

    if negative {
        format!("-{}{}", int_with_commas, dec_part)
    } else {
        format!("{}{}", int_with_commas, dec_part)
    }
}

fn add_commas_base10(s: &str) -> String {
    let len = s.len();
    if len <= 3 {
        return s.to_string();
    }

    let mut result = String::new();
    let first_group = len % 3;
    let first_group = if first_group == 0 { 3 } else { first_group };

    result.push_str(&s[..first_group]);

    let mut i = first_group;
    while i < len {
        result.push(',');
        result.push_str(&s[i..i+3]);
        i += 3;
    }

    result
}

fn format_base_n(n: f64, base: u32, fix: usize) -> String {
    // Step 1: Round the number to 'fix' decimal places in base 10
    let rounded_str = format!("{:.prec$}", n, prec = fix);
    let rounded: f64 = rounded_str.parse().unwrap_or(n);

    let negative = rounded < 0.0;
    let abs_n = rounded.abs();

    // Step 2: Convert integer part to base N using f64 arithmetic
    let int_val = abs_n.floor();
    let frac_val = abs_n - int_val;

    let int_str = if int_val == 0.0 {
        "0".to_string()
    } else {
        f64_to_base_n(int_val, base)
    };

    // Prepend minus sign if negative
    let signed_int = if negative {
        format!("-{}", int_str)
    } else {
        int_str
    };

    // Step 3: Pad to at least 10 chars (for fixed-width display)
    let padded = if signed_int.len() < 10 {
        format!("{:>10}", signed_int)
    } else {
        signed_int
    };

    // Step 4: Group with commas every 3 from right
    let int_grouped = group_digits_3(&padded);

    // Step 5: Convert fractional part to base N
    let frac_digits = convert_fraction_to_base_n(frac_val, base, fix);

    // Step 6: Strip trailing zeros but keep at least 1 digit
    let frac_trimmed = frac_digits.trim_end_matches('0');
    let frac_display = if frac_trimmed.is_empty() {
        "0".to_string()
    } else {
        frac_trimmed.to_string()
    };

    format!("{}.{}", int_grouped, frac_display)
}

fn f64_to_base_n(mut n: f64, base: u32) -> String {
    if n == 0.0 {
        return "0".to_string();
    }

    let base_f = base as f64;
    let mut digits = Vec::new();

    while n >= 1.0 {
        let d = (n % base_f) as u32;
        digits.push(digit_to_char(d));
        n = (n / base_f).floor();
    }

    digits.reverse();
    digits.into_iter().collect()
}

fn convert_fraction_to_base_n(mut frac: f64, base: u32, digits: usize) -> String {
    let base_f = base as f64;
    let mut result = String::new();

    for _ in 0..digits {
        frac *= base_f;
        let d = frac.floor() as u32;
        result.push(digit_to_char(d));
        frac -= frac.floor();
    }

    result
}

fn digit_to_char(d: u32) -> char {
    if d < 10 {
        (b'0' + d as u8) as char
    } else {
        (b'A' + (d - 10) as u8) as char
    }
}

fn group_digits_3(s: &str) -> String {
    let len = s.len();
    if len == 0 {
        return String::new();
    }

    let first_group_size = len % 3;
    let first_group_size = if first_group_size == 0 { 3 } else { first_group_size };

    let mut result = String::new();
    result.push_str(&s[..first_group_size]);

    let mut i = first_group_size;
    while i < len {
        result.push(',');
        result.push_str(&s[i..i+3]);
        i += 3;
    }

    result
}

// ============ MAIN PROCESSING ============

pub fn process_expression(input: &str, prev_ans: f64, angle_unit: &AngleUnit) -> Result<f64, CalcError> {
    let tokens = tokenize(input)?;
    let tokens = insert_implicit_mult(tokens);
    validate_functions(&tokens)?;
    let tokens = balance_parens(tokens);
    let rpn = shunting_yard(&tokens)?;
    let result = evaluate(&rpn, prev_ans, angle_unit)?;
    Ok(result)
}

// ============ CLI PARSING ============

struct Config {
    fix: usize,
    base: u32,
    angle_unit: AngleUnit,
    input: Option<String>,
}

fn print_help(prog: &str) {
    println!("Calculator REPL similar to bc(1)");
    println!();
    println!("Usage: {} [OPTIONS] [INPUT]", prog);
    println!();
    println!("Arguments:");
    println!("  [INPUT]  Optional expression string to run eva in command mode");
    println!();
    println!("Options:");
    println!("  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]");
    println!("  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]");
    println!("  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]");
    println!("  -h, --help                     Print help");
    println!("  -V, --version                  Print version");
}

fn print_version() {
    println!("eva 0.3.1");
}

fn parse_args() -> Result<Config, (String, i32)> {
    let args: Vec<String> = std::env::args().collect();
    let prog = args.get(0).map(|s| s.as_str()).unwrap_or("eva");

    let mut fix = 10usize;
    let mut base = 10u32;
    let mut angle_unit = AngleUnit::Degree;
    let mut input: Option<String> = None;
    let mut i = 1;
    let mut end_of_options = false;

    while i < args.len() {
        let arg = &args[i];

        if end_of_options {
            if input.is_some() {
                return Err((format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg, prog), 2));
            }
            input = Some(arg.clone());
            i += 1;
            continue;
        }

        if arg == "--" {
            end_of_options = true;
            i += 1;
            continue;
        }

        if arg == "-h" || arg == "--help" {
            print_help(prog);
            std::process::exit(0);
        }

        if arg == "-V" || arg == "--version" {
            print_version();
            std::process::exit(0);
        }

        // Handle -f/--fix
        if arg == "-f" || arg == "--fix" {
            i += 1;
            if i >= args.len() {
                return Err((format!("a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'."), 2));
            }
            let val = &args[i];
            match val.parse::<usize>() {
                Ok(v) => {
                    if v < 1 || v > 64 {
                        return Err((format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", val, val), 2));
                    }
                    fix = v;
                }
                Err(_) => {
                    return Err((format!("error: invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2));
                }
            }
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--fix=") {
            match val.parse::<usize>() {
                Ok(v) => {
                    if v < 1 || v > 64 {
                        return Err((format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", val, val), 2));
                    }
                    fix = v;
                }
                Err(_) => {
                    return Err((format!("error: invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2));
                }
            }
            i += 1;
            continue;
        }

        // Handle -b/--base
        if arg == "-b" || arg == "--base" {
            i += 1;
            if i >= args.len() {
                return Err((format!("a value is required for '--base <RADIX>' but none was supplied\n\nFor more information, try '--help'."), 2));
            }
            let val = &args[i];
            match val.parse::<u32>() {
                Ok(v) => {
                    if v < 1 || v > 36 {
                        return Err((format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", val, val), 2));
                    }
                    base = v;
                }
                Err(_) => {
                    return Err((format!("error: invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2));
                }
            }
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--base=") {
            match val.parse::<u32>() {
                Ok(v) => {
                    if v < 1 || v > 36 {
                        return Err((format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", val, val), 2));
                    }
                    base = v;
                }
                Err(_) => {
                    return Err((format!("error: invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2));
                }
            }
            i += 1;
            continue;
        }

        // Handle -a/--angle_unit
        if arg == "-a" || arg == "--angle_unit" {
            i += 1;
            if i >= args.len() {
                return Err((format!("a value is required for '--angle_unit <angle_unit>' but none was supplied\n\nFor more information, try '--help'."), 2));
            }
            let val = &args[i];
            angle_unit = match val.as_str() {
                "degree" => AngleUnit::Degree,
                "radian" => AngleUnit::Radian,
                "gradian" => AngleUnit::Gradian,
                _ => return Err((format!("error: invalid value '{}' for '--angle_unit <angle_unit>': [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.", val), 2)),
            };
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--angle_unit=") {
            angle_unit = match val {
                "degree" => AngleUnit::Degree,
                "radian" => AngleUnit::Radian,
                "gradian" => AngleUnit::Gradian,
                _ => return Err((format!("error: invalid value '{}' for '--angle_unit <angle_unit>': [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.", val), 2)),
            };
            i += 1;
            continue;
        }

        if arg.starts_with('-') {
            // Unknown option or negative number passed without --
            return Err((format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg, prog), 2));
        }

        // Positional argument
        if input.is_some() {
            return Err((format!("error: unexpected argument '{}' found", arg), 2));
        }
        input = Some(arg.clone());
        i += 1;
    }

    Ok(Config { fix, base, angle_unit, input })
}

// ============ HISTORY ============

fn get_history_dir() -> Option<std::path::PathBuf> {
    let home = std::env::var("HOME").ok()?;
    let mut path = std::path::PathBuf::from(home);
    path.push(".local/share/eva");
    Some(path)
}

fn load_history(dir: &std::path::Path) -> (Vec<String>, bool) {
    let hist_file = dir.join("history.txt");
    if hist_file.exists() {
        if let Ok(content) = std::fs::read_to_string(&hist_file) {
            let lines: Vec<String> = content.lines()
                .filter(|l| !l.starts_with('#'))
                .map(|l| l.to_string())
                .collect();
            return (lines, true);
        }
    }
    (Vec::new(), false)
}

fn save_history(dir: &std::path::Path, history: &[String]) {
    let _ = std::fs::create_dir_all(dir);
    let hist_file = dir.join("history.txt");
    let mut content = String::from("#V2\n");
    for (i, line) in history.iter().enumerate() {
        if i > 0 {
            content.push('\n');
        }
        content.push_str(line);
    }
    let _ = std::fs::write(&hist_file, content);
}

// ============ REPL ============

fn run_repl(config: &Config) {
    let hist_dir = get_history_dir();
    let mut history: Vec<String> = Vec::new();
    let mut history_existed = false;

    if let Some(ref dir) = hist_dir {
        let (hist, existed) = load_history(dir);
        history = hist;
        history_existed = existed;
    }

    if !history_existed {
        println!("No previous history.");
    }

    let mut prev_ans = 0.0f64;
    let stdin = io::stdin();
    let is_tty = is_stdin_tty();

    if is_tty {
        loop {
            print!("> ");
            let _ = io::stdout().flush();

            let mut line = String::new();
            match stdin.lock().read_line(&mut line) {
                Ok(0) => break, // EOF (Ctrl+D)
                Ok(_) => {
                    let trimmed = line.trim_end_matches('\n').trim_end_matches('\r').to_string();
                    let trimmed = trimmed.trim().to_string();
                    if trimmed.is_empty() {
                        continue;
                    }

                    history.push(trimmed.clone());

                    match process_expression(&trimmed, prev_ans, &config.angle_unit) {
                        Ok(result) => {
                            prev_ans = result;
                            println!("{}", format_number(result, config.base, config.fix));
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                        }
                    }
                }
                Err(_) => break,
            }
        }
    } else {
        let mut lines = stdin.lock().lines();
        loop {
            match lines.next() {
                None => break,
                Some(Ok(line)) => {
                    let trimmed = line.trim().to_string();
                    if trimmed.is_empty() {
                        continue;
                    }

                    history.push(trimmed.clone());

                    match process_expression(&trimmed, prev_ans, &config.angle_unit) {
                        Ok(result) => {
                            prev_ans = result;
                            println!("{}", format_number(result, config.base, config.fix));
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                        }
                    }
                }
                Some(Err(_)) => break,
            }
        }
    }

    if let Some(ref dir) = hist_dir {
        save_history(dir, &history);
    }
}

fn is_stdin_tty() -> bool {
    unsafe { libc_isatty(0) != 0 }
}

extern "C" {
    #[link_name = "isatty"]
    fn libc_isatty(fd: i32) -> i32;
}

// ============ MAIN ============

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err((msg, code)) => {
            eprintln!("{}", msg);
            std::process::exit(code);
        }
    };

    if let Some(ref input) = config.input {
        match process_expression(input, 0.0, &config.angle_unit) {
            Ok(result) => {
                println!("{}", format_number(result, config.base, config.fix));
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    } else {
        run_repl(&config);
    }
}
