// ============ ERRORS ============

#[derive(Debug, Clone)]
pub enum CalcError {
    Syntax(String),
    Parser(String),
    Math(String),
    Domain(String),
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CalcError::Syntax(msg) => write!(f, "Syntax Error: {}", msg),
            CalcError::Parser(msg) => write!(f, "Parser Error: {}", msg),
            CalcError::Math(msg) => write!(f, "Math Error: {}", msg),
