// ============ FUNCTION/CONSTANT LISTS ============

const FUNCTIONS: &[&str] = &[
    "asin", "acos", "atan", "acsc", "asec", "acot",
    "sinh", "cosh", "tanh",
    "sin", "cos", "tan", "csc", "sec", "cot",
    "log10", "log2", "log", "ln",
    "sqrt", "ceil", "floor", "abs",
    "nroot",
];

const CONSTANTS: &[&str] = &["pi", "e"];

fn is_function(name: &str) -> bool {
    FUNCTIONS.contains(&name)
}

fn is_constant(name: &str) -> bool {
    CONSTANTS.contains(&name)
}

fn function_arg_count(name: &str) -> usize {
    match name {
        "log" | "nroot" => 2,
        _ => 1,
    }
}

// Find the longest prefix of `s` that is a known function or constant.
// Returns Some((token, remaining_digits)) or None.
fn match_identifier(s: &str) -> Option<(Token, &str)> {
    // Try from longest to shortest (functions list is ordered longest-first where needed)
    let mut best: Option<(Token, &str)> = None;
    let mut best_len = 0;

    for &name in FUNCTIONS {
        if s.starts_with(name) && name.len() > best_len {
            let remaining = &s[name.len()..];
            // Remaining must be all digits (or empty) for a valid match
            if remaining.chars().all(|c| c.is_ascii_digit() || c == '.') {
                best = Some((Token::Function(name.to_string()), remaining));
                best_len = name.len();
            } else if remaining.is_empty() {
                best = Some((Token::Function(name.to_string()), remaining));
                best_len = name.len();
            }
        }
    }

    for &name in CONSTANTS {
        if s.starts_with(name) && name.len() > best_len {
            let remaining = &s[name.len()..];
            if remaining.chars().all(|c| c.is_ascii_digit() || c == '.') {
                best = Some((Token::Constant(name.to_string()), remaining));
                best_len = name.len();
            } else if remaining.is_empty() {
                best = Some((Token::Constant(name.to_string()), remaining));
                best_len = name.len();
            }
        }
    }

    best
