struct Config {
    fix: usize,
    base: u32,
    angle_unit: AngleUnit,
    input: Option<String>,
}

fn print_help() {
    println!("Calculator REPL similar to bc(1)");
    println!();
    println!("Usage: eva [OPTIONS] [INPUT]");
    println!();
    println!("Arguments:");
    println!("  [INPUT]  Optional expression string to run eva in command mode");
    println!();
    println!("Options:");
    println!("  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]");
    println!("  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]");
    println!("  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]");
    println!("  -h, --help                     Print help");
    println!("  -V, --version                  Print version");
}

fn print_version() {
    println!("eva 0.3.1");
}

fn parse_args() -> Result<Config, (String, i32)> {
    let args: Vec<String> = std::env::args().collect();

    let mut fix = 10usize;
    let mut base = 10u32;
    let mut angle_unit = AngleUnit::Degree;
    let mut input: Option<String> = None;
    let mut i = 1;
    let mut end_of_options = false;

    while i < args.len() {
        let arg = &args[i];

        if end_of_options {
            if input.is_some() {
                let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: eva [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg);
                return Err((msg, 2));
            }
            input = Some(arg.clone());
            i += 1;
            continue;
        }

        if arg == "--" {
            end_of_options = true;
            i += 1;
            continue;
        }

        if arg == "-h" || arg == "--help" {
            print_help();
            std::process::exit(0);
        }

        if arg == "-V" || arg == "--version" {
            print_version();
            std::process::exit(0);
        }

        if arg == "-f" || arg == "--fix" {
            i += 1;
            if i >= args.len() {
                return Err(("a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'.".to_string(), 2));
            }
            let val = &args[i];
            match val.parse::<usize>() {
                Ok(v) if v >= 1 && v <= 64 => fix = v,
                Ok(v) => return Err((format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", v, v), 2)),
                Err(_) => return Err((format!("error: invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2)),
            }
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--fix=") {
            match val.parse::<usize>() {
                Ok(v) if v >= 1 && v <= 64 => fix = v,
                Ok(v) => return Err((format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.", v, v), 2)),
                Err(_) => return Err((format!("error: invalid value '{}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2)),
            }
            i += 1;
            continue;
        }

        if arg == "-b" || arg == "--base" {
            i += 1;
            if i >= args.len() {
                return Err(("a value is required for '--base <RADIX>' but none was supplied\n\nFor more information, try '--help'.".to_string(), 2));
            }
            let val = &args[i];
            match val.parse::<u32>() {
                Ok(v) if v >= 1 && v <= 36 => base = v,
                Ok(v) => return Err((format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", v, v), 2)),
                Err(_) => return Err((format!("error: invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2)),
            }
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--base=") {
            match val.parse::<u32>() {
                Ok(v) if v >= 1 && v <= 36 => base = v,
                Ok(v) => return Err((format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.", v, v), 2)),
                Err(_) => return Err((format!("error: invalid value '{}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.", val), 2)),
            }
            i += 1;
            continue;
        }

        if arg == "-a" || arg == "--angle_unit" {
            i += 1;
            if i >= args.len() {
                return Err(("a value is required for '--angle_unit <angle_unit>' but none was supplied\n\nFor more information, try '--help'.".to_string(), 2));
            }
            let val = &args[i];
            angle_unit = match val.as_str() {
                "degree" => AngleUnit::Degree,
                "radian" => AngleUnit::Radian,
                "gradian" => AngleUnit::Gradian,
                _ => return Err((format!("error: invalid value '{}' for '--angle_unit <angle_unit>': [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.", val), 2)),
            };
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--angle_unit=") {
            angle_unit = match val {
                "degree" => AngleUnit::Degree,
                "radian" => AngleUnit::Radian,
                "gradian" => AngleUnit::Gradian,
                _ => return Err((format!("error: invalid value '{}' for '--angle_unit <angle_unit>': [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.", val), 2)),
            };
            i += 1;
            continue;
        }

        if arg.starts_with('-') {
            let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: eva [OPTIONS] [INPUT]\n\nFor more information, try '--help'.", arg, arg, arg);
            return Err((msg, 2));
        }

        if input.is_some() {
            let msg = format!("error: unexpected argument '{}' found", arg);
            return Err((msg, 2));
        }
        input = Some(arg.clone());
        i += 1;
    }

    Ok(Config { fix, base, angle_unit, input })
}

// ============ HISTORY ============

fn get_history_dir() -> Option<std::path::PathBuf> {
    let home = std::env::var("HOME").ok()?;
    let mut path = std::path::PathBuf::from(home);
    path.push(".local/share/eva");
    Some(path)
}

fn load_history(dir: &std::path::Path) -> (Vec<String>, bool) {
    let hist_file = dir.join("history.txt");
    if hist_file.exists() {
        if let Ok(content) = std::fs::read_to_string(&hist_file) {
            let lines: Vec<String> = content.lines()
                .filter(|l| !l.starts_with('#'))
                .map(|l| l.to_string())
                .collect();
            return (lines, true);
        }
    }
    (Vec::new(), false)
}

fn save_history(dir: &std::path::Path, history: &[String]) {
    let _ = std::fs::create_dir_all(dir);
    let hist_file = dir.join("history.txt");
    let mut content = String::from("#V2\n");
    for (idx, line) in history.iter().enumerate() {
        if idx > 0 {
            content.push('\n');
        }
        content.push_str(line);
    }
    let _ = std::fs::write(&hist_file, content);
}

// ============ REPL ============

fn run_repl(config: &Config) {
    let hist_dir = get_history_dir();
    let mut history: Vec<String> = Vec::new();
    let mut history_existed = false;

    if let Some(ref dir) = hist_dir {
        let (hist, existed) = load_history(dir);
        history = hist;
        history_existed = existed;
    }

    if !history_existed {
        println!("No previous history.");
    }

    let mut prev_ans = 0.0f64;
    let stdin = io::stdin();
    let is_tty = is_stdin_tty();

    if is_tty {
        loop {
            print!("> ");
            let _ = io::stdout().flush();

            let mut line = String::new();
            match stdin.lock().read_line(&mut line) {
                Ok(0) => break, // EOF (Ctrl+D)
                Ok(_) => {
                    let trimmed = line.trim_end_matches('\n').trim_end_matches('\r');

                    if trimmed.is_empty() {
                        // Empty line -> output 0
                        println!("{}", format_number(0.0, config.base, config.fix));
                        continue;
                    }

                    history.push(trimmed.to_string());

                    match process_expression(trimmed, prev_ans, &config.angle_unit) {
                        Ok(result) => {
                            prev_ans = result;
                            println!("{}", format_number(result, config.base, config.fix));
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                        }
                    }
                }
                Err(_) => break,
            }
        }
    } else {
        let mut lines = stdin.lock().lines();
        loop {
            match lines.next() {
                None => break,
                Some(Ok(line)) => {
                    let trimmed = line.trim_end_matches('\n').trim_end_matches('\r');

                    if trimmed.is_empty() {
                        println!("{}", format_number(0.0, config.base, config.fix));
                        continue;
                    }

                    history.push(trimmed.to_string());

                    match process_expression(trimmed, prev_ans, &config.angle_unit) {
                        Ok(result) => {
                            prev_ans = result;
                            println!("{}", format_number(result, config.base, config.fix));
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                        }
                    }
                }
                Some(Err(_)) => break,
            }
        }
    }

    if let Some(ref dir) = hist_dir {
        save_history(dir, &history);
    }
}

fn is_stdin_tty() -> bool {
    unsafe { libc_isatty(0) != 0 }
}

extern "C" {
    #[link_name = "isatty"]
    fn libc_isatty(fd: i32) -> i32;
}

// ============ MAIN ============

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err((msg, code)) => {
            eprintln!("{}", msg);
            std::process::exit(code);
        }
    };

    if let Some(ref input) = config.input {
        // Command mode
        if input.is_empty() {
            // Empty input -> no output
            return;
        }

        // Check if input is whitespace-only
        if input.trim().is_empty() {
            println!("{}", format_number(0.0, config.base, config.fix));
            return;
        }

        match process_expression(input, 0.0, &config.angle_unit) {
            Ok(result) => {
                println!("{}", format_number(result, config.base, config.fix));
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    } else {
        // REPL mode
        run_repl(&config);
    }
}
