with open('src/main.rs', 'r') as f:
    content = f.read()

# Find the LParen handling and change it to track whether args exist
# Change:
#             Token::LParen => {
#                 stack.push(StackItem::LParen(1));
#             }
# To:
#             Token::LParen => {
#                 stack.push(StackItem::LParen(0)); // 0 = no args yet
#             }

content = content.replace(
    '            Token::LParen => {\n                stack.push(StackItem::LParen(1));\n            }',
    '            Token::LParen => {\n                stack.push(StackItem::LParen(0)); // 0 = no args yet\n            }'
)

# Also fix the comma handling - it should increment from 0 to 1 for first arg, etc.
# Hmm, but comma means "delimiter between args". If we start at 0:
# f(a) -> LParen(0), process 'a', at RParen: argc = ?
# f(a,b) -> LParen(0), comma -> LParen(1), at RParen: argc = ?
# So we need to +1 at end if there were any args.

# The fix is: when we hit RParen, if the top of OUTPUT before the LParen had items,
# then argc = comma_count + 1, else argc = 0.

# Simplest approach: track whether prev token was LParen when hitting RParen.
# If tokens[prev] == LParen, argc = 0, else argc = comma_count + 1.

# I'll change the RParen handling to use prev_token:
# (Since we already track prev_token in the loop)

# Change the comma increment:
old_comma = '''                if let Some(StackItem::LParen(ref mut count)) = stack.last_mut() {
                    *count += 1;
                }'''
new_comma = '''                if let Some(StackItem::LParen(ref mut count)) = stack.last_mut() {
                    *count += 1;
                }
                // Note: count tracks number of commas (args-1)'''
content = content.replace(old_comma, new_comma)

# Change the RParen handling to compute argc correctly
old_rparen = '''                let argc = if let Some(StackItem::LParen(count)) = stack.pop() {
                    count
                } else {
                    1
                };'''
new_rparen = '''                let argc = if let Some(StackItem::LParen(comma_count)) = stack.pop() {
                    // If previous token was LParen, we have 0 args
                    // Otherwise we have comma_count + 1 args
                    match prev_token {
                        Some(Token::LParen) => 0,
                        Some(Token::Comma) => comma_count, // trailing comma edge case
                        _ => comma_count + 1,
                    }
                } else {
                    1
                };'''
content = content.replace(old_rparen, new_rparen)

with open('src/main.rs', 'w') as f:
    f.write(content)

print("Done")
