                // Read all alphanumeric chars
                let start = i;
                while i < chars.len() && (chars[i].is_ascii_alphanumeric()) {
                    i += 1;
                }
                let ident: String = chars[start..i].iter().collect();

                // Try to find the longest known prefix
                if let Some((tok, remaining)) = match_identifier(&ident) {
                    // We found a match!
                    // Advance i to point right after the matched name (not the full ident)
                    // This allows remaining chars to be re-processed
                    let matched_len = ident.len() - remaining.len();
                    // Backtrack i to after the matched portion
                    i = start + matched_len;
                    tokens.push(tok);
